<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { abrirCiclo,avanzarFase,detalleCiclo,finalizarCiclo,listarCiclos,type Ciclo,type Distrito,type Sector } from '../services/ciclos'
const phases:[string,string][]=[['lecturas','Toma de lectura'],['critica','Crítica de lecturas'],['avisos','Avisos de alto consumo'],['pre_facturacion','Pre-facturación'],['impresion','Impresión de recibos'],['reparto','Reparto de recibos'],['revision_cortados','Revisión de cortados'],['corte_deudores','Corte deudores'],['corte_convenios','Corte convenios']]
const districts=ref<Distrito[]>([]),detail=ref<Ciclo|null>(null),sector=ref<Sector|null>(null),modal=ref<'crear'|null>(null),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),schedule=reactive<Record<string,string>>({})
async function load(){loading.value=true;error.value='';try{districts.value=(await listarCiclos()).distritos}catch(e){error.value=msg(e)}finally{loading.value=false}}async function show(id:number){try{detail.value=await detalleCiclo(id)}catch(e){error.value=msg(e)}}
function open(s:Sector){sector.value=s;phases.forEach((phase)=>{const k=phase[0]!;schedule[`fecha_inicial_${k}`]='';schedule[`fecha_finaliza_${k}`]=''});modal.value='crear'}
async function create(){if(!sector.value)return;for(const phase of phases){const k=phase[0]!,inicio=schedule[`fecha_inicial_${k}`]||'',fin=schedule[`fecha_finaliza_${k}`]||'';if(!inicio||!fin){error.value='Complete las fechas de todas las fases.';return}if(inicio>fin){error.value='La fecha inicial no puede superar la fecha final.';return}}saving.value=true;try{await abrirCiclo(sector.value.id,schedule);success.value='Ciclo aperturado correctamente.';modal.value=null;await load()}catch(e){error.value=msg(e)}finally{saving.value=false}}
async function next(){if(!detail.value||!confirm(`¿Avanzar el ciclo desde la fase ${detail.value.fase}?`))return;try{detail.value=await avanzarFase(detail.value.id);success.value='El ciclo avanzó a la siguiente fase.';await load()}catch(e){error.value=msg(e)}}async function finish(){if(!detail.value||!confirm('¿Finalizar este ciclo? Esta acción cerrará el proceso.'))return;try{await finalizarCiclo(detail.value.id);detail.value=null;success.value='Ciclo finalizado correctamente.';await load()}catch(e){error.value=msg(e)}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Facturación / Ciclos</nav><header class="hero"><div class="mark">CF</div><div><small>EVAN · FACTURACIÓN</small><h1>Administración de ciclos</h1><p>Cronograma y avance del proceso de facturación por sector.</p></div><strong>{{districts.reduce((n,d)=>n+d.sectores.length,0)}} sectores</strong></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><div v-if="loading" class="empty">Cargando ciclos…</div><section v-else class="districts"><article v-for="d in districts" :key="d.id"><header><div><small>DISTRITO</small><h2>{{d.nombre}}</h2></div><span>{{d.sectores.length}} sectores</span></header><div class="sectors"><div v-for="s in d.sectores" :key="s.id"><div><b>{{s.nombre}}</b><small v-if="s.ciclo">{{s.ciclo.nombre}}</small><small v-else>Sin ciclo activo</small></div><em v-if="s.ciclo">{{s.ciclo.fase}}</em><button v-if="s.ciclo" @click="show(s.ciclo.id)">Administrar</button><button v-else class="new" @click="open(s)">Generar ciclo</button></div></div></article></section>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="cycle"><header><div><small>CICLO DE FACTURACIÓN</small><h2>{{detail.nombre}}</h2><p>Fase actual: {{detail.fase}}</p></div><button @click="detail=null">×</button></header><div class="timeline"><article v-for="f in detail.fases" :key="f.id" :class="{current:f.actual,done:f.completada}"><i>{{f.completada?'✓':f.id}}</i><div><b>{{f.nombre}}</b><span>{{f.inicio||'—'}} → {{f.fin||'—'}}</span></div><em>{{f.actual?'Fase actual':f.completada?'Completada':'Pendiente'}}</em></article></div><footer><button class="clear" @click="detail=null">Cerrar</button><button v-if="detail.fase_id<10" @click="next">Avanzar fase →</button><button v-else class="finish" @click="finish">Finalizar ciclo</button></footer></section></div>
<div v-if="modal==='crear'&&sector" class="backdrop" @mousedown.self="modal=null"><form class="cycle create" @submit.prevent="create"><header><div><small>NUEVO CICLO</small><h2>Cronograma · {{sector.nombre}}</h2><p>Defina las fechas de todas las fases antes de iniciar.</p></div><button type="button" @click="modal=null">×</button></header><div class="schedule"><fieldset v-for="([key,name],i) in phases" :key="key"><legend>{{i+1}}. {{name}}</legend><label>Inicio<input v-model="schedule[`fecha_inicial_${key}`]" type="date" required></label><label>Finalización<input v-model="schedule[`fecha_finaliza_${key}`]" type="date" required></label></fieldset></div><footer><button type="button" class="clear" @click="modal=null">Cancelar</button><button :disabled="saving">{{saving?'Creando…':'Crear ciclo'}}</button></footer></form></div></div></template>
<style scoped>
.page{--a:#287fbc;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:700}.hero small,.cycle small,.districts small{color:var(--a);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.cycle header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.flash{padding:10px;font-size:.63rem}.good{color:#287258;background:#edf9f3}.error{color:#a13f43;background:#fff0f0}.empty{padding:50px;text-align:center;background:#fff;font-size:.6rem}.districts{margin-top:13px;display:grid;grid-template-columns:1fr 1fr;gap:11px}.districts>article{border-radius:10px;background:#fff;overflow:hidden}.districts>article>header{padding:14px 16px;display:flex;justify-content:space-between;color:#fff;background:var(--a)}.districts header small{color:#cbeafb}.districts h2{margin:2px 0;font-size:.72rem}.districts header span{font-size:.5rem}.sectors>div{padding:11px 15px;display:flex;align-items:center;gap:8px;border-bottom:1px solid #e9edef}.sectors>div>div{flex:1}.sectors b,.sectors small{display:block;font-size:.53rem}.sectors small{margin-top:2px;color:#839096}.sectors em{padding:4px 7px;border-radius:8px;color:#277759;background:#eaf8f1;font-size:.45rem;font-style:normal}.sectors button,.cycle footer button{padding:7px 9px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.48rem}.sectors .new{background:#687c86}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.cycle{width:min(100%,850px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.cycle>header{display:flex}.cycle h2{margin:2px 0;font-size:1rem}.cycle>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.timeline{margin-top:15px}.timeline article{padding:10px;display:flex;align-items:center;gap:10px;border-left:3px solid #dce3e6;border-bottom:1px solid #edf0f2}.timeline article.current{border-color:var(--a);background:#edf7fb}.timeline article.done{border-color:#2a9a6d}.timeline i{width:27px;height:27px;display:grid;place-items:center;border-radius:50%;color:#fff;background:#aab5ba;font-size:.49rem;font-style:normal}.timeline .done i{background:#2a9a6d}.timeline .current i{background:var(--a)}.timeline div{flex:1}.timeline b,.timeline span{display:block;font-size:.52rem}.timeline span{color:#859096}.timeline em{font-size:.47rem;font-style:normal}.cycle footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.finish{background:#29916a!important}.create{width:min(100%,950px)}.schedule{display:grid;grid-template-columns:1fr 1fr;gap:8px}.schedule fieldset{padding:10px;border:1px solid #dbe3e6;border-radius:7px}.schedule legend{padding:0 4px;color:var(--a);font-size:.52rem;font-weight:700}.schedule label{display:inline-block;width:50%;padding:3px;font-size:.48rem}.schedule input{width:100%;padding:7px;border:1px solid #d8e0e4;border-radius:5px;font:inherit;font-size:.52rem}@media(max-width:800px){.districts{grid-template-columns:1fr}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:560px){.schedule{grid-template-columns:1fr}.sectors>div{align-items:flex-start;flex-wrap:wrap}.sectors>div>div{min-width:100%}}
</style>
